function binarySearchByEmail(sortedUsers, email) {
  let lo = 0, hi = sortedUsers.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const midEmail = sortedUsers[mid].email;
    if (midEmail === email) return sortedUsers[mid];
    if (midEmail < email) lo = mid + 1;
    else hi = mid - 1;
  }
  return null;
}

