function isWithinRange(value, from, to) {
  return value >= from && value <= to;
}

function countInRange(sortedNumbers, from, to) {
  let count = 0;
  for (const n of sortedNumbers) {
    if (n >= from && n <= to) count++;
  }
  return count;
}

function findLowerBoundLinear(sortedNumbers, target) {
  for (let i = 0; i < sortedNumbers.length; i++) {
    if (sortedNumbers[i] >= target) return i;
  }
  return sortedNumbers.length;
}

function findUpperBoundLinear(sortedNumbers, target) {
  for (let i = 0; i < sortedNumbers.length; i++) {
    if (sortedNumbers[i] > target) return i;
  }
  return sortedNumbers.length;
}

function sliceBetweenIndices(arr, startIndex, endIndexExclusive) {
  return arr.slice(startIndex, endIndexExclusive);
}

function mapKeysToArray(map) {
  return [...map.keys()];
}

function mapValuesInRange(map, from, to) {
  const results = [];
  for (const [key, value] of map) {
    if (key >= from && key <= to) results.push(value);
  }
  return results;
}

function clampToRange(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

