function rangeQuerySorted(sortedUsers, fromEmail, toEmail) {
  let lo = 0, hi = sortedUsers.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (sortedUsers[mid].email < fromEmail) lo = mid + 1;
    else hi = mid;
  }
  const results = [];
  for (let i = lo; i < sortedUsers.length && sortedUsers[i].email <= toEmail; i++) {
    results.push(sortedUsers[i]);
  }
  return results;
}

